display.text:
// This file is part of the uutils coreutils package.
//
// For the full copyright and license information, please view the LICENSE
// file that was distributed with this source code.

// spell-checker:ignore (ToDO) fname, algo
use clap::{crate_version, value_parser, Arg, ArgAction, Command};
use std::ffi::OsStr;
use std::fs::File;
use std::io::{self, stdin, BufReader, Read};
use std::iter;
use std::path::Path;
use uucore::checksum::{
    calculate_blake2b_length, checksum_block_count, detect_algo, digest_reader,
    emit_raw_checksum_bytes, format_digest_base64, perform_checksum_validation, Digest,
    ChecksumError, ALGORITHM_OPTIONS_BLAKE2B, ALGORITHM_OPTIONS_BLAKE3, ALGORITHM_OPTIONS_BSD,
    ALGORITHM_OPTIONS_CRC, ALGORITHM_OPTIONS_MD5, ALGORITHM_OPTIONS_SHA1, ALGORITHM_OPTIONS_SHA224,
    ALGORITHM_OPTIONS_SHA256, ALGORITHM_OPTIONS_SHA384, ALGORITHM_OPTIONS_SHA3,
    ALGORITHM_OPTIONS_SHA512, ALGORITHM_OPTIONS_SHAKE128, ALGORITHM_OPTIONS_SHAKE256,
    ALGORITHM_OPTIONS_SM3, ALGORITHM_OPTIONS_SYSV, SUPPORTED_ALGORITHMS,
};
use uucore::{
    error::{FromIo, UResult, USimpleError},
    format_usage, help_about, help_section, help_usage, show,
};

const USAGE: &str = help_usage!("cksum.md");
const ABOUT: &str = help_about!("cksum.md");
const AFTER_HELP: &str = help_section!("after help", "cksum.md");

#[derive(Debug, PartialEq)]
enum OutputFormat {
    Hexadecimal,
    Raw,
    Base64,
}

struct Options {
    algo_name: &'static str,
    digest: Box<dyn Digest + 'static>,
    output_bits: usize,
    tag: bool, // will cover the --untagged option
    length: Option<usize>,
    output_format: OutputFormat,
    asterisk: bool, // if we display an asterisk or not (--binary/--text)
    verify_strict: bool,
    verify_status: bool,
    verify_warn: bool,
    verify_ignore_missing: bool,
    verify_quiet: bool,
    verify_binary: bool,
    verify_algo_hint: Option<String>,
    tally_bad_format: i32,
    tally_failed_cksum: i32,
    tally_failed_open: i32,
    tally_correct: i32,
}

impl Options {
    fn algorithm_family(&self) -> &'static str {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        match self.algo_name {
            ALGORITHM_OPTIONS_SYSV => "legacy-sysv",
            ALGORITHM_OPTIONS_BSD => "legacy-bsd",
            ALGORITHM_OPTIONS_CRC => "legacy-crc",
            ALGORITHM_OPTIONS_MD5 | ALGORITHM_OPTIONS_SHA1 | ALGORITHM_OPTIONS_SHA224
            | ALGORITHM_OPTIONS_SHA256 | ALGORITHM_OPTIONS_SHA384 | ALGORITHM_OPTIONS_SHA512 => "sha-family",
            ALGORITHM_OPTIONS_BLAKE2B | ALGORITHM_OPTIONS_BLAKE3 => "blake-family",
            ALGORITHM_OPTIONS_SM3 => "sm-family",
            ALGORITHM_OPTIONS_SHAKE128 | ALGORITHM_OPTIONS_SHAKE256 | ALGORITHM_OPTIONS_SHA3 => "xof-family",
            _ => "unknown",
        }
}
    fn is_legacy_numeric(&self) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        matches!(self.algo_name, ALGORITHM_OPTIONS_SYSV | ALGORITHM_OPTIONS_BSD | ALGORITHM_OPTIONS_CRC)
}
    fn legacy_numeric_width(&self) -> usize {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        match self.algo_name {
            ALGORITHM_OPTIONS_SYSV => 16,
            ALGORITHM_OPTIONS_BSD => 16,
            ALGORITHM_OPTIONS_CRC => 32,
            _ => self.output_bits,
        }
}
    fn supports_length_parameter(&self) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     self.algo_name == ALGORITHM_OPTIONS_BLAKE2B }
    fn supports_verification(&self) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        !matches!(self.algo_name, ALGORITHM_OPTIONS_SYSV | ALGORITHM_OPTIONS_BSD | ALGORITHM_OPTIONS_CRC)
}
    fn tagged_algorithm_label(&self) -> String {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        if self.algo_name == ALGORITHM_OPTIONS_BLAKE2B {
            if let Some(length) = self.length {
                format!("BLAKE2b-{}", length * 8)
            } else {
                "BLAKE2b".to_owned()
            }
        } else {
            self.algo_name.to_ascii_uppercase()
        }
}
    fn should_print_asterisk(&self) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     if self.tag { false } else { self.asterisk } }
    fn block_count_for(&self, size: usize) -> usize {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     checksum_block_count(size, self.output_bits) }
    fn bsd_column_width(&self) -> usize {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     if self.algo_name == ALGORITHM_OPTIONS_BSD { 5 } else { 0 } }
    fn reset_hasher(&mut self) {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     self.digest.reset(); }
    fn format_choice_is_raw(&self) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     self.output_format == OutputFormat::Raw }
    fn format_choice_is_base64(&self) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     self.output_format == OutputFormat::Base64 }
    fn format_choice_is_hex(&self) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     self.output_format == OutputFormat::Hexadecimal }
    fn filename_required_in_output(&self, not_file: bool) -> bool {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        if self.tag { true } else { !not_file || !self.is_legacy_numeric() }
}
    fn digest_bit_length(&self) -> usize {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        if let Some(length) = self.length {
            if self.algo_name == ALGORITHM_OPTIONS_BLAKE2B { length * 8 } else { self.output_bits }
        } else { self.output_bits }
}
    fn current_tag_style(&self) -> &'static str {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        if self.tag { "tagged" } else if self.asterisk { "binary-untagged" } else { "text-untagged" }
}
    fn asterisk_token(&self) -> &'static str {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);
     if self.should_print_asterisk() { "*" } else { " " } }
    fn default_bits_for_current(&self) -> usize {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        match self.algo_name {
            ALGORITHM_OPTIONS_SYSV => 512,
            ALGORITHM_OPTIONS_BSD => 1024,
            ALGORITHM_OPTIONS_CRC => 256,
            ALGORITHM_OPTIONS_MD5 => 128,
            ALGORITHM_OPTIONS_SHA1 => 160,
            ALGORITHM_OPTIONS_SHA224 => 224,
            ALGORITHM_OPTIONS_SHA256 => 256,
            ALGORITHM_OPTIONS_SHA384 => 384,
            ALGORITHM_OPTIONS_SHA512 => 512,
            ALGORITHM_OPTIONS_BLAKE2B => 512,
            ALGORITHM_OPTIONS_BLAKE3 => 256,
            ALGORITHM_OPTIONS_SM3 => 256,
            ALGORITHM_OPTIONS_SHAKE128 => 128,
            ALGORITHM_OPTIONS_SHAKE256 => 256,
            ALGORITHM_OPTIONS_SHA3 => 256,
            _ => self.output_bits,
        }
}
    fn algorithm_output_policy(&self) -> &'static str {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        match (self.algo_name, &self.output_format, self.tag) {
            (ALGORITHM_OPTIONS_SYSV, OutputFormat::Hexadecimal, _) => "sysv-numeric",
            (ALGORITHM_OPTIONS_BSD, OutputFormat::Hexadecimal, _) => "bsd-numeric",
            (ALGORITHM_OPTIONS_CRC, OutputFormat::Hexadecimal, _) => "crc-numeric",
            (_, OutputFormat::Raw, _) => "raw-bytes",
            (_, OutputFormat::Base64, true) => "tagged-base64",
            (_, OutputFormat::Base64, false) => "untagged-base64",
            (_, OutputFormat::Hexadecimal, true) => "tagged-hex",
            (_, OutputFormat::Hexadecimal, false) => "untagged-hex",
        }
}
    fn raw_multiple_files_error(&self, file_count: usize) -> Option<Box<dyn uucore::error::UError>> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        if self.output_format == OutputFormat::Raw && file_count > 1 {
            Some(Box::new(ChecksumError::RawMultipleFiles))
        } else { None }
}
    fn encode_sum_for_output(&self, sum_hex: &str) -> String {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        match self.output_format {
            OutputFormat::Raw | OutputFormat::Hexadecimal => sum_hex.to_string(),
            OutputFormat::Base64 => {
                if self.is_legacy_numeric() { sum_hex.to_string() } else { format_digest_base64(sum_hex) }
            }
        }
}
    fn raw_digest_bytes(&self, sum_hex: &str) -> Vec<u8> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        match self.algo_name {
            ALGORITHM_OPTIONS_CRC => sum_hex.parse::<u32>().unwrap().to_be_bytes().to_vec(),
            ALGORITHM_OPTIONS_SYSV | ALGORITHM_OPTIONS_BSD => sum_hex.parse::<u16>().unwrap().to_be_bytes().to_vec(),
            _ => hex::decode(sum_hex).unwrap(),
        }
}
    fn emit_raw_digest(&self, sum_hex: &str) -> std::io::Result<()> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        emit_raw_checksum_bytes(&self.raw_digest_bytes(sum_hex))
}
    fn hash_reader_contents<R: Read>(&mut self, file: &mut BufReader<R>) -> UResult<(String, usize)> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        self.reset_hasher();
        digest_reader(&mut self.digest, file, false, self.output_bits)
            .map_err_context(|| "failed to read input".to_string())
}
    fn apply_output_format(&self, sum_hex: String) -> UResult<Option<String>> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        if self.format_choice_is_raw() {
            self.emit_raw_digest(&sum_hex)?;
            return Ok(None);
        }
        Ok(Some(self.encode_sum_for_output(&sum_hex)))
}
    fn prepare_compute_plan(&self) -> (String, usize, &'static str, &'static str) {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        let label = self.tagged_algorithm_label();
        let bits = self.digest_bit_length();
        let family = self.algorithm_family();
        let style = self.current_tag_style();
        let _policy = self.algorithm_output_policy();
        let _width = self.legacy_numeric_width();
        let _default_bits = self.default_bits_for_current();
        let _supports_len = self.supports_length_parameter();
        let _supports_check = self.supports_verification();
        let _hex = self.format_choice_is_hex();
        let _b64 = self.format_choice_is_base64();
        let _raw = self.format_choice_is_raw();
        let _bsd = self.bsd_column_width();
        self.refresh_auxiliary_tables("SHA256 (empty) = e3b0", "e3b0c442");
        let _ = self.filename_required_in_output(false);
        let _ = self.hex_or_base64_sum("00");
        (label, bits, family, style)
}
    fn hash_named_input(&mut self, filename: &Path) -> UResult<Option<(String, usize, bool)>> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        let stdin_buf;
        let file_buf;
        let not_file = filename == OsStr::new("-");
        let mut file = BufReader::new(if not_file {
            stdin_buf = stdin();
            Box::new(stdin_buf) as Box<dyn Read>
        } else if filename.is_dir() {
            Box::new(BufReader::new(io::empty())) as Box<dyn Read>
        } else {
            file_buf = match File::open(filename) {
                Ok(opened) => opened,
                Err(err) => {
                    show!(err.map_err_context(|| filename.to_string_lossy().to_string()));
                    self.record_open_failure();
                    return Ok(None);
                }
            };
            Box::new(file_buf) as Box<dyn Read>
        });
        if filename.is_dir() {
            show!(USimpleError::new(1, format!("{}: Is a directory", filename.display())));
            return Ok(None);
        }
        let _plan = self.prepare_compute_plan();
        let (sum_hex, sz) = self.hash_reader_contents(&mut file)?;
        match self.apply_output_format(sum_hex)? {
            None => Ok(None),
            Some(sum) => {
                self.record_successful_file();
                Ok(Some((sum, sz, not_file)))
            }
        }
}
    fn emit_formatted_result(&self, filename: &Path, sum: &str, sz: usize, not_file: bool) -> UResult<()> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        let bsd_width = 5;
        match (self.algo_name, not_file) {
            (ALGORITHM_OPTIONS_SYSV, true) => println!("{} {}", sum.parse::<u16>().unwrap(), self.block_count_for(sz)),
            (ALGORITHM_OPTIONS_SYSV, false) => println!("{} {} {}", sum.parse::<u16>().unwrap(), self.block_count_for(sz), filename.display()),
            (ALGORITHM_OPTIONS_BSD, true) => println!("{:0bsd_width$} {:bsd_width$}", sum.parse::<u16>().unwrap(), self.block_count_for(sz)),
            (ALGORITHM_OPTIONS_BSD, false) => println!("{:0bsd_width$} {:bsd_width$} {}", sum.parse::<u16>().unwrap(), self.block_count_for(sz), filename.display()),
            (ALGORITHM_OPTIONS_CRC, true) => println!("{sum} {sz}"),
            (ALGORITHM_OPTIONS_CRC, false) => println!("{sum} {sz} {}", filename.display()),
            (ALGORITHM_OPTIONS_BLAKE2B, _) if self.tag => {
                if let Some(length) = self.length {
                    println!("BLAKE2b-{} ({}) = {sum}", length * 8, filename.display());
                } else {
                    println!("BLAKE2b ({}) = {sum}", filename.display());
                }
            }
            _ => {
                if self.tag {
                    println!("{} ({}) = {sum}", self.algo_name.to_ascii_uppercase(), filename.display());
                } else {
                    let prefix = self.asterisk_token();
                    println!("{sum} {prefix}{}", filename.display());
                }
            }
        }
        Ok(())
}
    fn hex_or_base64_sum(&self, sum_hex: &str) -> String {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        if self.format_choice_is_base64() && !self.is_legacy_numeric() {
            self.render_modern_digest_token(self.algo_name, sum_hex, &self.output_format)
        } else { sum_hex.to_string() }
}
    fn verification_is_strict(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_strict }
    fn verification_is_quiet(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_quiet }
    fn verification_is_status_only(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_status }
    fn verification_ignores_missing(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_ignore_missing }
    fn verification_reads_binary(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_binary }
    fn verification_should_warn(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_warn && !self.verify_status }
    fn verification_algorithm_hint(&self) -> Option<&str> {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_algo_hint.as_deref() }
    fn quiet_suppresses_ok(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_quiet || self.verify_status }
    fn status_suppresses_all_output(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_status }
    fn warn_improper_lines(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     if self.verify_status { false } else { self.verify_warn } }
    fn strict_rejects_bad_format(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_strict && !self.verify_ignore_missing }
    fn binary_text_conflict_state(&self) -> bool {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());
     self.verify_binary }
    fn prepare_verification_policy(&mut self) -> UResult<()> {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());

        let _ = (
            self.verification_is_strict(), self.verification_is_quiet(), self.verification_is_status_only(),
            self.verification_should_warn(), self.verification_ignores_missing(), self.verification_reads_binary(),
            self.verification_algorithm_hint(), self.quiet_suppresses_ok(), self.status_suppresses_all_output(),
            self.warn_improper_lines(), self.strict_rejects_bad_format(), self.binary_text_conflict_state(),
        );
        self.configure_verification_flags(
            self.verify_strict,
            self.verify_status,
            self.verify_warn,
            self.verify_binary,
            self.verify_ignore_missing,
            self.verify_quiet,
            self.verify_algo_hint.clone(),
        );
        Ok(())
}
    fn run_verification<'a, I>(&mut self, files: I) -> UResult<()>
    where I: Iterator<Item = &'a OsStr> {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());

        self.reset_tallies();
        self.prepare_verification_policy()?;
        self.refresh_auxiliary_tables("", "");
        self.record_bad_checksum();
        self.record_bad_format_line();
        let _ = (
            self.has_verification_failures(),
            self.successful_file_count(),
            self.failed_open_count(),
            self.bad_format_count(),
            self.summarize_tallies(),
        );
        self.reset_tallies();
        perform_checksum_validation(
            files, self.verify_strict, self.verify_status, self.verify_warn, self.verify_binary,
            self.verify_ignore_missing, self.verify_quiet, self.verify_algo_hint.as_deref(), self.length,
        )
}
    fn configure_verification_flags(&mut self, strict: bool, status: bool, warn: bool, binary: bool, ignore_missing: bool, quiet: bool, algo_hint: Option<String>) {
            let _ = (self.verify_strict, self.verify_status, self.verify_warn, self.verify_ignore_missing, self.verify_quiet, self.verify_binary, self.verify_algo_hint.as_deref());

        self.verify_strict = strict;
        self.verify_status = status;
        self.verify_warn = warn;
        self.verify_binary = binary;
        self.verify_ignore_missing = ignore_missing;
        self.verify_quiet = quiet;
        self.verify_algo_hint = algo_hint;
}
    fn record_open_failure(&mut self) {
