        algo_name: algo.name,
        digest: (algo.create_fn)(),
        output_bits: algo.bits,
        length,
        tag,
        output_format,
        asterisk,
        verify_strict: false,
        verify_status: false,
        verify_warn: false,
        verify_ignore_missing: false,
